var toAuxiliar = tw.local.to.split(',');
var toFinal    = [];
var duplicate  = false;

    for (var i = 0; i < toAuxiliar.length; i++){
         duplicate  = false;
         for (var j = 0; j < toFinal.length; j++){
              if(toAuxiliar[i] == toFinal[j]){
                 duplicate  = true;
                 break;
              }
         }
         if(duplicate == false){
             toFinal[toFinal.length] = toAuxiliar[i];
         }
    }

    tw.local.to = toFinal.toString();
}

