function checkDuplicateEmails(email){

    var check = true;

    if(tw.local.recondicionamento.instalacao.destinatarios == undefined ||
       tw.local.recondicionamento.instalacao.destinatarios == null){
           return true;
    } 

    if(email != undefined && email != null){

    var dests = tw.system.serializer.fromXml(tw.local.recondicionamento.instalacao.destinatarios.toXML());

        for (var k = 0; k < dests.listLength; k++) {
            if(dests[k].enderecoEmail == email){
                check = false;
                return check;
            }
        }

    }   

