    var dests = tw.system.serializer.fromXml(tw.local.recondicionamento.secretariaComercial.destinatarios.toXML());

        for (var k = 0; k < dests.listLength; k++) {
            if(dests[k].enderecoEmail == email){
                check = false;
                return check;
            }
        }

    }   

    return check;

}

