function checkMultiOrSinglePaint(){
    var itemIt     = 0 ;
    var paintCount = 0;  
    while ( itemIt < tw.local.ioItems.listLength  && paintCount < 2 ){  
         if( tw.local.ioItems[itemIt].pintar == true ){
             paintCount++;
         }
         itemIt++
    }
    return (paintCount >= 2 ? true : false)
}

function calculateEstimatedItemPrices(paintTypeIncrease){

    var priceIt = 0 ;
    var itemIt  = 0 ;
    var isMulti = checkMultiOrSinglePaint();
    tw.local.ioBudget.hoursPanelWorkDefault = 0;
    tw.local.ioBudget.hoursPaintWorkDefault = 0; 

    while ( priceIt < tw.local.ioReconditioning.priceTableConfig.itemPricing.listLength && itemIt < tw.local.ioItems.listLength ) {        

           if ( Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].itemId) == Number(tw.local.ioItems[itemIt].numItem) ) {

                    tw.local.ioItems[itemIt].estimativa =0;

                    var hasPaintRequest   = 0;

                            //checkbox pintar
                    if( tw.local.ioItems[itemIt].pintar == true ){

                        if ( isMulti == true ) {                             

                            tw.local.ioBudget.totalEstimativa    += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].paintMultiPrice)*Number(paintTypeIncrease);
                            tw.local.ioItems[itemIt].estimativa  += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].paintMultiPrice)*Number(paintTypeIncrease);
                            hasPaintRequest = Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].paintMultiPrice)*Number(paintTypeIncrease);

                            //moHourDefaultValues
                            tw.local.ioBudget.hoursPanelWorkDefault += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].hourPanelMultiValue);
                            tw.local.ioBudget.hoursPaintWorkDefault += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].hourPaintMultiValue); 


                        } else  {

                            tw.local.ioBudget.totalEstimativa    += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].paintUniquePrice)*Number(paintTypeIncrease);
                            tw.local.ioItems[itemIt].estimativa  += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].paintUniquePrice)*Number(paintTypeIncrease);  
                            hasPaintRequest = Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].paintUniquePrice)*Number(paintTypeIncrease);      

                            //moHourDefaultValues           
                            tw.local.ioBudget.hoursPanelWorkDefault += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].hourPanelSingleValue);
                            tw.local.ioBudget.hoursPaintWorkDefault += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].hourPaintSingleValue);      
                        }             

                    }            


                            //checkbox reparar
                    if(  tw.local.ioItems[itemIt].reparar == true ){

                            tw.local.ioBudget.totalEstimativa    += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].repair);
                            tw.local.ioItems[itemIt].estimativa  += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].repair);

                    }


                             //checkbox polir
                    if(tw.local.ioItems[itemIt].polir == true ){

                            tw.local.ioBudget.totalEstimativa    += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].polish);
                            tw.local.ioItems[itemIt].estimativa  += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].polish);

                            //moHourDefaultValues
                            tw.local.ioBudget.hoursPaintWorkDefault+=Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].hourPolishPaintValue)    

                    }


                             //checkbox substituir
                    if( tw.local.ioItems[itemIt].substituir == true ){

                            tw.local.ioBudget.totalEstimativa    += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].replace);
                            tw.local.ioItems[itemIt].estimativa  += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].replace);

                    }


                            //checkbox 1/2
                    if(  tw.local.ioItems[itemIt].meiaPeca == true ){

                        if ( hasPaintRequest > 0 ) {

                            tw.local.ioBudget.totalEstimativa   = tw.local.ioBudget.totalEstimativa   - hasPaintRequest;
                            tw.local.ioItems[itemIt].estimativa = tw.local.ioItems[itemIt].estimativa - hasPaintRequest;

                        } 

                        //moHourDefaultValues
                        tw.local.ioBudget.hoursPanelWorkDefault+=Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].hourPanelHalfValue);
                        tw.local.ioBudget.hoursPaintWorkDefault+=Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].hourPaintHalfValue);    

                        tw.local.ioBudget.totalEstimativa    += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].paintHalfPrice)*Number(paintTypeIncrease);                            
                        tw.local.ioItems[itemIt].estimativa  += Number(tw.local.ioReconditioning.priceTableConfig.itemPricing[priceIt].paintHalfPrice)*Number(paintTypeIncrease);

                    }

               var tmPrice = 0;

               if(tw.local.ioItems[itemIt].pintar == true){
                   tmPrice = Number( Number(tw.local.ioReconditioning.priceTableConfig.hourPrice) * Number(tw.local.ioItems[itemIt].tempoReparacao) );     

                   tmPrice = tmPrice + (Number(tw.local.ioItems[itemIt].tempoReparacao)*Number(tw.local.ioReconditioning.priceTableConfig.hourPaintPrice));

               } else{
                   tmPrice = Number( Number(tw.local.ioReconditioning.priceTableConfig.hourPrice) * Number(tw.local.ioItems[itemIt].tempoReparacao) );   

               }

               tw.local.ioBudget.totalEstimativa   =  Number(tw.local.ioBudget.totalEstimativa) + tmPrice;           
               tw.local.ioItems[itemIt].estimativa =  Number(tw.local.ioItems[itemIt].estimativa) + tmPrice;        
               tw.local.ioItems[itemIt].preco      =  tw.local.ioItems[itemIt].estimativa;

               tw.local.ioItems[itemIt].estimativa = tw.local.ioItems[itemIt].estimativa.toFixed(2);     
               tw.local.ioItems[itemIt].preco      = tw.local.ioItems[itemIt].preco.toFixed(2);  

               itemIt++;  

           } 

           priceIt++;          

      } 

}


