                            //log.info(Number(tw.local.ioReconditioning.priceTableConfig.budgetPricing[idx].paintMultiPrice));

                            tw.local.ioBudget.totalEstimativa        += Number(tw.local.ioReconditioning.priceTableConfig.budgetPricing[idx].paintMultiPrice)*paintTypeIncrease;                   
