                            //moHourDefaultValues           
                            tw.local.ioBudget.hoursPanelWorkDefault += Number(tw.local.ioReconditioning.priceTableConfig.budgetPricing[idx].hourPanelLargeValue);
                            tw.local.ioBudget.hoursPaintWorkDefault += Number(tw.local.ioReconditioning.priceTableConfig.budgetPricing[idx].hourPaintLargeValue);      


                    } else if(tw.local.ioReconditioning.orcamentos[tw.local.ioReconditioning.orcamentos.listLength-1].vehicleSize != undefined &&
