                            //log.info("current estimativa");
                            //log.info(Number(tw.local.ioReconditioning.priceTableConfig.budgetPricing[idx].paintUniquePrice));

                            tw.local.ioBudget.totalEstimativa        += Number(tw.local.ioReconditioning.priceTableConfig.budgetPricing[idx].paintUniquePrice)*paintTypeIncrease;                   
                            tw.local.ioBudget.pinturaGeralEstimativa = Number(tw.local.ioReconditioning.priceTableConfig.budgetPricing[idx].paintUniquePrice)*paintTypeIncrease;

                             //moHourDefaultValues           
                            tw.local.ioBudget.hoursPanelWorkDefault += Number(tw.local.ioReconditioning.priceTableConfig.budgetPricing[idx].hourPanelMediumValue);
                            tw.local.ioBudget.hoursPaintWorkDefault += Number(tw.local.ioReconditioning.priceTableConfig.budgetPricing[idx].hourPaintMediumValue);      



                    } else if(tw.local.ioReconditioning.orcamentos[tw.local.ioReconditioning.orcamentos.listLength-1].vehicleSize != undefined &&
