function checkBpmHostFromUrl(url){
    if(url && url.length > 0){
        var oldUrl = java.net.URL(url);
        if(oldUrl && oldUrl.getHost() && oldUrl.getHost().toUpperCase() == "BPM.GRUPOSALVADORCAETANO.PT"){
            url = new java.net.URL(oldUrl.getProtocol(), java.net.InetAddress.getLocalHost().getHostName()+".sc.pt", 9444, oldUrl.getFile()).toString();    
        }
    }
return url;
}

