function Sc_AddWeekDays(date, WORK_DAYS){
  //var dateAux = new tw.object.Date(date);

  var dateAux = new tw.object.Date();
  dateAux = date;


  var weekday;
  var weekdaysInc = 0;

  var sdf = new java.text.SimpleDateFormat("yyyy-MM-dd");    
  var cal = java.util.Calendar.getInstance();
  cal.setTime(dateAux.toNativeDate());

       while (weekdaysInc < WORK_DAYS){
                weekday = cal.get(cal.DAY_OF_WEEK);  

                if(weekday == 6 ){
                  cal.add(cal.DAY_OF_YEAR, 3); 
                }
                else if(weekday == 7){
                  cal.add(cal.DAY_OF_YEAR, 2); 
                }
                else{
                  cal.add(cal.DAY_OF_YEAR, 1);
                }                       
                   weekdaysInc++;               
         }           

             var d = sdf.format(cal.getTime());

             dateAux.parse(d, "yyyy-MM-dd");

           return dateAux;

}

